use super::*;use serde_json::{Value,json};use std::panic::{catch_unwind,AssertUnwindSafe};
use util::org::apache::poi::util::LittleEndianByteArrayOutput::LittleEndianByteArrayOutput;
use crate::cn::wps::et::ss::formula::ptg::Ptg::{Ptg,ptgValues,serializePtgs};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");json!({"result":s.split(':').next().unwrap()})}}}
fn hex(b:&[u8])->String{b.iter().map(|b|format!("{b:02x}")).collect()}
fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
fn expression(r:&FormulaRecord)->Value{let ps=r.getParsedExpression();let b=serializePtgs(&ptgValues(&ps));let again=r.getParsedExpression();json!({"length":ps.borrow().len(),"bytes":hex(&b),"sameAgain":Rc::ptr_eq(&ps,&again)})}
fn state(r:&FormulaRecord)->Value{let mut out=LittleEndianByteArrayOutput::new();let mut record=call(||r.serialize(&mut out));record["bytes"]=json!(hex(&out.get_bytes()));json!({"row":r.getRow(),"col":r.getColumn(),"xf":r.getXFIndex(),"valueBits":format!("{:016x}",r.getValue().to_bits()),"options":r.getOptions(),"shared":r.isSharedFormula(),"always":r.isAlwaysCalc(),"onLoad":r.isCalcOnLoad(),"external":r.BIFF2ExternalLinkFormula(),"hasString":r.hasCachedResultString(),"cacheType":r.getCachedResultType(),"boolean":call(||r.getCachedBooleanValue()),"error":call(||r.getCachedErrorValue()),"expression":call(||expression(r)),"record":record,"sid":r.getSid()})}
fn flags()->Vec<Value>{let r=FormulaRecord::new();(0..65536).map(|i|{r.setOptions(i as i16);let mut a=vec![json!(r.isSharedFormula()),json!(r.isAlwaysCalc()),json!(r.isCalcOnLoad())];for b in [false,true]{r.setOptions(i as i16);r.setSharedFormula(b);a.push(json!(r.getOptions()));r.setOptions(i as i16);r.setAlwaysCalc(b);a.push(json!(r.getOptions()));r.setOptions(i as i16);r.setCalcOnLoad(b);a.push(json!(r.getOptions()));}json!(a)}).collect()}
fn command(r:&FormulaRecord,p:&Value){match p["op"].as_str().unwrap(){"value"=>r.setValue(f64::from_bits(u64::from_str_radix(p["bits"].as_str().unwrap(),16).unwrap())),"empty"=>r.setCachedResultTypeEmptyString(),"string"=>r.setCachedResultTypeString(),"error"=>r.setCachedResultErrorCode(p["value"].as_i64().unwrap()as i32),"bool"=>r.setCachedResultBoolean(p["value"].as_bool().unwrap()),"formulaNull"=>r.setFormula(None),"expression"=>r.setParsedExpression(p["bytes"].as_str().map(|s|ptgArray(Ptg::readTokens((s.len()/2)as i32,&bytes(s),SpreadsheetVersion::EXCEL97)))),"encoded"=>r.setFormula(Some(Rc::new(RefCell::new(Formula::Formula(Some(Rc::new(RefCell::new(Vec::new().into_boxed_slice()))),p["size"].as_i64().unwrap()as i32,Some(SpreadsheetVersion::EXCEL97)))))),"nullTokens"=>r.setParsedExpression(Some(Rc::new(RefCell::new(vec![None].into_boxed_slice())))),_=>panic!("unknown")}}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_formula_record_public_model_and_serializers(){let root=std::path::PathBuf::from(std::env::var("SS_CORE_PROOF_ROOT").unwrap_or_else(|_|env!("CARGO_MANIFEST_DIR").into()));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/formula-record-r0b66");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let mut histories=vec![];for h in input["histories"].as_array().unwrap(){let r=FormulaRecord::new();r.setRow(h["row"].as_i64().unwrap()as i32);r.setColumn(h["col"].as_i64().unwrap()as i16);r.setXFIndex(h["xf"].as_i64().unwrap()as i32);r.setOptions(h["options"].as_i64().unwrap()as i16);let mut rows=vec![];for p in h["commands"].as_array().unwrap(){let mut row=call(||command(&r,p));let clone=r.clone();row["state"]=state(&r);row["clone"]=state(&clone);row["sameFormula"]=json!(match(r.getFormula(),clone.getFormula()){(None,None)=>true,(Some(a),Some(b))=>Rc::ptr_eq(&a,&b),_=>false});if let Some(f)=r.getFormula(){f.borrow_mut().setValue(Some(Rc::new(RefCell::new(vec![30,9,0].into_boxed_slice()))),3);row["afterFormulaMutation"]=state(&clone);}rows.push(row);}histories.push(rows);}let mut ctors=vec![];for s in input["constructors"].as_array().unwrap(){let mut r=None;let mut row=call(||{r=Some(FormulaRecord::new__bytes(s.as_str().map(|s|Rc::new(RefCell::new(bytes(s).into_boxed_slice())))));});if let Some(r)=r{row["state"]=state(&r);}ctors.push(row);}let ids=[0,-1,-9,-10,i32::MIN,1,2].into_iter().map(|n|json!({"stream":call(||Rc::ptr_eq(&Ptg::readTokens__stream__array(n,&[],false,SpreadsheetVersion::EXCEL97),&Ptg::EMPTY_PTG_ARRAY())),"bytes":call(||Rc::ptr_eq(&Ptg::readTokens__array(n,&[],SpreadsheetVersion::EXCEL97),&Ptg::EMPTY_PTG_ARRAY()))})).collect::<Vec<_>>();let actual=json!({"arrayIdentities":ids,"flags":flags(),"default":state(&FormulaRecord::new()),"histories":histories,"constructors":ctors});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
